'use strict';
const DB_NAME='djfolsoe-music-server-v1800';
const DB_VERSION=1;
const TRACKS='tracks', HISTORY='history', PLANS='plans', SETTINGS='settings';
let dbPromise;
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains(TRACKS)){const s=d.createObjectStore(TRACKS,{keyPath:'id'});s.createIndex('artist','artist');s.createIndex('title','title');s.createIndex('genre','genre');s.createIndex('year','year');s.createIndex('spotifyId','spotifyId',{unique:false});}if(!d.objectStoreNames.contains(HISTORY))d.createObjectStore(HISTORY,{keyPath:'id'});if(!d.objectStoreNames.contains(PLANS))d.createObjectStore(PLANS,{keyPath:'id'});if(!d.objectStoreNames.contains(SETTINGS))d.createObjectStore(SETTINGS,{keyPath:'key'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return dbPromise}
function tx(store,mode='readonly'){return db().then(d=>d.transaction(store,mode).objectStore(store))}
async function putMany(store,items){if(!items.length)return;const d=await db();await new Promise((resolve,reject)=>{const t=d.transaction(store,'readwrite'),s=t.objectStore(store);items.forEach(x=>s.put(x));t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
async function put(store,item){return putMany(store,[item])}
async function getAll(store){const s=await tx(store);return new Promise((resolve,reject)=>{const r=s.getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function get(store,key){const s=await tx(store);return new Promise((resolve,reject)=>{const r=s.get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function delMany(store,ids){const d=await db();await new Promise((resolve,reject)=>{const t=d.transaction(store,'readwrite'),s=t.objectStore(store);ids.forEach(id=>s.delete(id));t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
async function clear(store){const s=await tx(store,'readwrite');return new Promise((resolve,reject)=>{const r=s.clear();r.onsuccess=resolve;r.onerror=()=>reject(r.error)})}
async function count(store){const s=await tx(store);return new Promise((resolve,reject)=>{const r=s.count();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}


function norm(v=''){return String(v).normalize('NFKD').replace(/\p{Diacritic}/gu,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function trackKey(t){return t.spotifyId?`spotify:${t.spotifyId}`:`${norm(t.artist)}|${norm(t.title)}|${norm(t.version||'')}`}
function csvEscape(v){const s=String(v??'');return /[",;\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s}
function download(name,text,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportMaster(tracks){const h=['Artist','Title','Version','Album','Year','Country','Label','Genre','Subgenre','BPM','Key','Camelot','Energy','Rating','Crowd Rating','Spotify ID','Spotify URI','Spotify URL','ISRC','Duration ms','Last Played','Play Count','Tags','Playlists','Source','Verified'];const lines=[h.join(',')];for(const t of tracks)lines.push([t.artist,t.title,t.version,t.album,t.year,t.country,t.label,t.genre,t.subgenre,t.bpm,t.key,t.camelot,t.energy,t.rating,t.crowdRating,t.spotifyId,t.spotifyUri,t.spotifyUrl,t.isrc,t.durationMs,t.lastPlayed,t.playCount,(t.tags||[]).join('|'),(t.playlists||[]).join('|'),t.source,t.verified].map(csvEscape).join(','));return lines.join('\n')}
function exportSoundiiz(tracks){const h=['title','artist','album','isrc','platform','id'];return [h.join(','),...tracks.map(t=>[t.title,t.artist,t.album,t.isrc,'spotify',t.spotifyId].map(csvEscape).join(','))].join('\n')}
function exportTuneMyMusic(tracks){const h=['Track name','Artist name','Album','ISRC','Spotify URL'];return [h.join(','),...tracks.map(t=>[t.title,t.artist,t.album,t.isrc,t.spotifyUrl].map(csvEscape).join(','))].join('\n')}
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++;continue}if(c==='"'){quote=!quote;continue}if(!quote&&(c===','||c===';')){row.push(cell);cell='';continue}if(!quote&&(c==='\n'||c==='\r')){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';continue}cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
function parseImport(text,source='CSV'){const rows=parseCSV(text);if(rows.length<2)return[];const aliases={artist:['artist','artists','artist name','kunstner'],title:['title','track','track name','song','titel'],album:['album','album name'],spotifyId:['spotify id','track id'],spotifyUrl:['spotify url','track url','url'],isrc:['isrc'],year:['year','release year','release date'],genre:['genre'],subgenre:['subgenre','style'],bpm:['bpm','tempo'],key:['key','toneart'],camelot:['camelot'],energy:['energy','energi'],country:['country','land'],label:['label'],version:['version','mix'],playlist:['playlist','playlist name']};const map={};rows[0].forEach((h,i)=>{const n=norm(h);for(const [k,a] of Object.entries(aliases))if(a.some(x=>norm(x)===n)){map[k]=i;break}});const g=(r,k)=>map[k]===undefined?'':String(r[map[k]]||'').trim();return rows.slice(1).map(r=>{const id=g(r,'spotifyId')||crypto.randomUUID();return{id:`spotify:${id}`.includes('spotify:spotify:')?id:`spotify:${id}`,spotifyId:g(r,'spotifyId'),spotifyUri:g(r,'spotifyId')?`spotify:track:${g(r,'spotifyId')}`:'',artist:g(r,'artist'),title:g(r,'title'),album:g(r,'album'),version:g(r,'version'),year:Number(g(r,'year').slice(0,4))||null,country:g(r,'country'),label:g(r,'label'),genre:g(r,'genre'),subgenre:g(r,'subgenre'),bpm:Number(g(r,'bpm'))||null,key:g(r,'key'),camelot:g(r,'camelot'),energy:Number(g(r,'energy'))||5,spotifyUrl:g(r,'spotifyUrl'),isrc:g(r,'isrc'),durationMs:null,playlists:g(r,'playlist')?[g(r,'playlist')]:[],tags:[],rating:0,crowdRating:0,lastPlayed:null,playCount:0,source,verified:false,createdAt:new Date().toISOString()}}).filter(t=>t.artist&&t.title)}

const API='https://api.spotify.com/v1';
const TOKEN='djf_spotify_token',REFRESH='djf_spotify_refresh',CLIENT='djf_spotify_client';
class SpotifyClient{
 constructor(log=console.log){this.log=log;this.token=localStorage.getItem(TOKEN)||'';this.refresh=localStorage.getItem(REFRESH)||'';this.clientId=localStorage.getItem(CLIENT)||''}
 redirectUri(){return 'https://folsoetv.dk/music/admin.html'}
 async login(clientId){this.log('Starter Spotify-login…');this.clientId=clientId.trim();if(!this.clientId)throw new Error('Spotify Client ID mangler.');localStorage.setItem(CLIENT,this.clientId);const bytes=crypto.getRandomValues(new Uint8Array(64)),verifier=this.b64(bytes);sessionStorage.setItem('djf_pkce',verifier);const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)),challenge=this.b64(new Uint8Array(hash));const scope=['playlist-read-private','playlist-read-collaborative','playlist-modify-private','playlist-modify-public','user-library-read','user-read-recently-played','user-top-read','user-read-private'].join(' ');location.href='https://accounts.spotify.com/authorize?'+new URLSearchParams({client_id:this.clientId,response_type:'code',redirect_uri:this.redirectUri(),scope,code_challenge_method:'S256',code_challenge:challenge})}
 b64(bytes){return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
 async handleCallback(){const code=new URLSearchParams(location.search).get('code');if(!code)return false;const body=new URLSearchParams({client_id:localStorage.getItem(CLIENT),grant_type:'authorization_code',code,redirect_uri:this.redirectUri(),code_verifier:sessionStorage.getItem('djf_pkce')});const r=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok)throw new Error(await r.text());const d=await r.json();this.token=d.access_token;this.refresh=d.refresh_token||'';localStorage.setItem(TOKEN,this.token);if(this.refresh)localStorage.setItem(REFRESH,this.refresh);history.replaceState({},'',this.redirectUri());return true}
 async renew(){if(!this.refresh)throw new Error('Spotify-session udløbet. Forbind igen.');const body=new URLSearchParams({client_id:localStorage.getItem(CLIENT),grant_type:'refresh_token',refresh_token:this.refresh});const r=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok)throw new Error('Kunne ikke forny Spotify-login.');const d=await r.json();this.token=d.access_token;localStorage.setItem(TOKEN,this.token)}
 async api(path,opt={},retry=true){const url=path.startsWith('http')?path:API+path;const r=await fetch(url,{...opt,headers:{Authorization:`Bearer ${this.token}`,'Content-Type':'application/json',...(opt.headers||{})}});if(r.status===401&&retry){await this.renew();return this.api(path,opt,false)}if(r.status===429){const wait=Math.max(1,Number(r.headers.get('Retry-After')||2));this.log(`Spotify rate limit: venter ${wait} sek.`);await new Promise(x=>setTimeout(x,wait*1000));return this.api(path,opt,retry)}if(!r.ok)throw new Error(`${r.status}: ${await r.text()}`);return r.status===204?{}:r.json()}
 async profile(){return this.api('/me')}
 async allPages(path,extract=x=>x.items||[]){let url=path.startsWith('http')?path:API+path,out=[];while(url){const d=await this.api(url);out.push(...extract(d));url=d.next||null}return out}
 async playlists(){return this.allPages('/me/playlists?limit=50')}
 async playlistItems(id){return this.allPages(`/playlists/${id}/items?limit=50`,d=>d.items||[])}
 async savedTracks(){return this.allPages('/me/tracks?limit=50',d=>d.items||[])}
 async recent(){const d=await this.api('/me/player/recently-played?limit=50');return d.items||[]}
 async topTracks(){const periods=['short_term','medium_term','long_term'],out=[];for(const p of periods){const d=await this.api(`/me/top/tracks?limit=50&time_range=${p}`);out.push(...(d.items||[]).map(item=>({item,period:p})))}return out}
 async createPlaylist(name,description,uris,isPublic=false){const p=await this.api('/me/playlists',{method:'POST',body:JSON.stringify({name,description,public:isPublic})});for(let i=0;i<uris.length;i+=100){await this.api(`/playlists/${p.id}/items`,{method:'POST',body:JSON.stringify({uris:uris.slice(i,i+100)})});this.log(`${Math.min(i+100,uris.length)}/${uris.length} tilføjet til ${name}`)}return p}
 logout(){[TOKEN,REFRESH].forEach(x=>localStorage.removeItem(x));this.token='';this.refresh=''}
}
function spotifyTrack(item,source,playlistName=''){const t=item.track||item.item||item;if(!t||t.type!=='track'||!t.id)return null;return{id:`spotify:${t.id}`,spotifyId:t.id,spotifyUri:t.uri||`spotify:track:${t.id}`,spotifyUrl:t.external_urls?.spotify||'',artist:(t.artists||[]).map(a=>a.name).join('; '),title:t.name||'',album:t.album?.name||'',version:'',year:Number((t.album?.release_date||'').slice(0,4))||null,country:'',label:'',genre:'',subgenre:'',bpm:null,key:'',camelot:'',energy:5,isrc:t.external_ids?.isrc||'',durationMs:t.duration_ms||null,playlists:playlistName?[playlistName]:[],tags:[],rating:0,crowdRating:0,lastPlayed:null,playCount:0,source,verified:true,explicit:!!t.explicit,popularity:t.popularity??null,artwork:t.album?.images?.[1]?.url||t.album?.images?.[0]?.url||'',createdAt:new Date().toISOString()}}

const $=id=>document.getElementById(id);let tracks=[],plans=[],history=[],profiles=[],spotifyPlaylists=[];let currentPlan=null;
const log=m=>{$('log').textContent+=`[${new Date().toLocaleTimeString('da-DK')}] ${m}\n`;$('log').scrollTop=$('log').scrollHeight};
const sp=new SpotifyClient(log);
function tabs(){document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab,.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.panel).classList.add('active')})}
async function loadAll(){[tracks,plans,history,profiles]=await Promise.all([getAll(TRACKS),getAll(PLANS),getAll(HISTORY),fetch('data/show-profiles.json').then(r=>r.json())]);render();}
function render(){
 $('trackCount').textContent=tracks.length.toLocaleString('da-DK');$('verifiedCount').textContent=tracks.filter(t=>t.verified).length.toLocaleString('da-DK');$('playlistCount').textContent=new Set(tracks.flatMap(t=>t.playlists||[])).size.toLocaleString('da-DK');$('planCount').textContent=plans.length.toLocaleString('da-DK');
 const selectedGenre=$('genreFilter').value,selectedStatus=$('statusFilter').value,q=norm($('search').value);const genres=[...new Set(tracks.map(t=>t.genre).filter(Boolean))].sort();$('genreFilter').innerHTML='<option value="">Alle genrer</option>'+genres.map(g=>`<option ${g===selectedGenre?'selected':''}>${g}</option>`).join('');
 const filtered=tracks.filter(t=>(!q||norm(`${t.artist} ${t.title} ${t.album} ${(t.tags||[]).join(' ')} ${(t.playlists||[]).join(' ')}`).includes(q))&&(!selectedGenre||t.genre===selectedGenre)&&(!selectedStatus||(selectedStatus==='verified'?t.verified:!t.verified))).slice(0,800);
 $('trackRows').innerHTML=filtered.map(t=>`<tr><td><input type="checkbox" data-id="${t.id}"></td><td>${t.artist}</td><td>${t.title}</td><td>${t.album||''}</td><td>${t.year||''}</td><td>${t.genre||''}</td><td>${t.bpm||''}</td><td>${t.camelot||t.key||''}</td><td>${(t.playlists||[]).slice(0,2).join(', ')}</td><td class="${t.verified?'status-ready':'status-warn'}">${t.verified?'Klar':'Kontrol'}</td></tr>`).join('');
 $('showSelect').innerHTML=profiles.map(p=>`<option value="${p.id}">${p.name}</option>`).join('');
}
function playlistCard(p){const img=p.images?.[0]?.url||'';return `<label class="playlist-card"><input type="checkbox" data-playlist="${p.id}"><img src="${img}" alt=""><span class="info"><strong>${p.name}</strong><small>${p.owner?.display_name||''} · ${p.items?.total??p.tracks?.total??0} numre</small></span></label>`}
async function connectSpotify(){log('Forbind Spotify blev trykket.');await sp.login($('clientId').value)}
async function loadSpotify(){if(!sp.token)throw new Error('Forbind Spotify først.');const me=await sp.profile();$('spotifyStatus').textContent=`Forbundet: ${me.display_name||me.id}`;spotifyPlaylists=await sp.playlists();$('spotifyPlaylists').innerHTML=spotifyPlaylists.map(playlistCard).join('');$('spotifyPlaylistTotal').textContent=spotifyPlaylists.length;log(`${spotifyPlaylists.length} Spotify-playlister hentet.`)}
async function mergeIncoming(incoming){const map=new Map(tracks.map(t=>[t.id,t]));let added=0,merged=0;for(const t of incoming){if(!t)continue;if(map.has(t.id)){const old=map.get(t.id);map.set(t.id,{...old,...t,genre:old.genre||t.genre,tags:[...new Set([...(old.tags||[]),...(t.tags||[])])],playlists:[...new Set([...(old.playlists||[]),...(t.playlists||[])])],rating:old.rating||0,crowdRating:old.crowdRating||0,lastPlayed:old.lastPlayed||null,playCount:old.playCount||0});merged++}else{map.set(t.id,t);added++}}tracks=[...map.values()];await putMany(TRACKS,tracks);log(`${added} nye numre, ${merged} eksisterende numre flettet.`);render()}
async function importSelectedPlaylists(){const ids=[...document.querySelectorAll('[data-playlist]:checked')].map(x=>x.dataset.playlist);if(!ids.length)return alert('Vælg mindst én playliste.');let incoming=[],done=0;for(const id of ids){const p=spotifyPlaylists.find(x=>x.id===id);log(`Importerer ${p.name}...`);const items=await sp.playlistItems(id);incoming.push(...items.map(x=>spotifyTrack(x,`Spotify playlist: ${p.name}`,p.name)).filter(Boolean));done++;$('syncProgress').style.width=`${done/ids.length*100}%`}await mergeIncoming(incoming)}
async function importLiked(){log('Importerer Liked Songs...');const items=await sp.savedTracks();await mergeIncoming(items.map(x=>spotifyTrack(x,'Spotify Liked Songs','Liked Songs')).filter(Boolean))}
async function importRecent(){const items=await sp.recent();const incoming=items.map(x=>{const t=spotifyTrack(x,'Spotify Recently Played','Recently Played');if(t){t.lastPlayed=x.played_at;t.playCount=1}return t}).filter(Boolean);await mergeIncoming(incoming)}
async function importTop(){const items=await sp.topTracks();await mergeIncoming(items.map(x=>{const t=spotifyTrack(x,'Spotify Top Tracks',`Top Tracks ${x.period}`);if(t)t.tags.push(`Top ${x.period}`);return t}).filter(Boolean))}
async function fileImport(e){for(const f of e.target.files){const parsed=parseImport(await f.text(),f.name);await mergeIncoming(parsed)}e.target.value=''}
function eligible(t,p,cutoff){const text=norm(`${t.genre} ${t.subgenre} ${(t.tags||[]).join(' ')} ${(t.playlists||[]).join(' ')}`);const genre=p.genres.includes('Any')||p.genres.some(g=>text.includes(norm(g)));const en=Number(t.energy||5)>=p.minEnergy&&Number(t.energy||5)<=p.maxEnergy;const bpm=!t.bpm||(t.bpm>=p.bpmMin&&t.bpm<=p.bpmMax);const recent=t.lastPlayed&&new Date(t.lastPlayed)>=cutoff;return genre&&en&&bpm&&!recent&&t.spotifyUri}
function score(t){return Number(t.rating||0)*3+Number(t.crowdRating||0)*3+(t.verified?3:0)+(t.popularity||0)/25+Math.random()*4}
function generatePlan(){const p=profiles.find(x=>x.id===$('showSelect').value),date=$('showDate').value||new Date().toISOString().slice(0,10),cutoff=new Date();cutoff.setDate(cutoff.getDate()-p.repeatDays);const pool=tracks.filter(t=>eligible(t,p,cutoff)).sort((a,b)=>score(b)-score(a));const selected=[],artists=new Map();for(const t of pool){const a=norm(t.artist);if((artists.get(a)||0)>=2)continue;selected.push(t);artists.set(a,(artists.get(a)||0)+1);if(selected.length>=p.targetTracks)break}selected.sort((a,b)=>Number(a.energy||5)-Number(b.energy||5)||Number(a.bpm||0)-Number(b.bpm||0));currentPlan={id:crypto.randomUUID(),showId:p.id,showName:p.name,date,status:'Draft',trackIds:selected.map(t=>t.id),createdAt:new Date().toISOString()};renderPlan()}
function renderPlan(){const list=currentPlan.trackIds.map(id=>tracks.find(t=>t.id===id)).filter(Boolean);$('planTitle').textContent=`${currentPlan.showName} — ${currentPlan.date} — ${list.length} numre`;$('planRows').innerHTML=list.map((t,i)=>`<tr><td>${i+1}</td><td>${t.artist}</td><td>${t.title}</td><td>${t.bpm||''}</td><td>${t.camelot||t.key||''}</td><td>${t.energy||''}</td><td>${(t.tags||[]).join(', ')}</td></tr>`).join('');$('planDialog').showModal()}
async function approvePlan(){currentPlan.status='Approved';await put(PLANS,currentPlan);plans=await getAll(PLANS);render();log('Showplan godkendt og gemt.')}
async function publishPlan(){if(!sp.token)return alert('Forbind Spotify først.');const list=currentPlan.trackIds.map(id=>tracks.find(t=>t.id===id)).filter(Boolean),uris=list.map(t=>t.spotifyUri).filter(Boolean);const p=await sp.createPlaylist(`DJ FOLSOE — ${currentPlan.showName.toUpperCase()} — ${currentPlan.date}`,'Generated by DJ FOLSOE MUSIC SERVER V1800',uris,false);log(`Spotify-playliste oprettet: ${p.external_urls.spotify}`);window.open(p.external_urls.spotify,'_blank')}
async function markSelected(verified){const ids=new Set([...document.querySelectorAll('#trackRows input:checked')].map(x=>x.dataset.id));const changed=[];tracks=tracks.map(t=>{if(ids.has(t.id)){const n={...t,verified};changed.push(n);return n}return t});await putMany(TRACKS,changed);render()}
async function deleteSelected(){const ids=[...document.querySelectorAll('#trackRows input:checked')].map(x=>x.dataset.id);await delMany(TRACKS,ids);tracks=tracks.filter(t=>!ids.includes(t.id));render()}
async function exportWebsite(){download('music-database.json',JSON.stringify(tracks.map(({source,...t})=>t),null,2),'application/json')}
async function resetDb(){if(!confirm('Slet hele Music Server-databasen i denne browser?'))return;await Promise.all([clear(TRACKS),clear(HISTORY),clear(PLANS)]);tracks=[];plans=[];history=[];render()}
async function init(){log('Music Server V1800.1 JavaScript er startet.');tabs();$('clientId').value=localStorage.getItem('djf_spotify_client')||'c432abf4f8ad4e20b374e5fc0221fc2c';try{if(await sp.handleCallback())log('Spotify-login gennemført.')}catch(e){log('Spotify-fejl: '+e.message)}await loadAll();if(sp.token)loadSpotify().catch(e=>log(e.message))}
$('connectSpotify').onclick=()=>connectSpotify().catch(e=>log(e.message));$('refreshSpotify').onclick=()=>loadSpotify().catch(e=>log(e.message));$('importPlaylists').onclick=()=>importSelectedPlaylists().catch(e=>log(e.message));$('importLiked').onclick=()=>importLiked().catch(e=>log(e.message));$('importRecent').onclick=()=>importRecent().catch(e=>log(e.message));$('importTop').onclick=()=>importTop().catch(e=>log(e.message));$('fileImport').onchange=e=>fileImport(e).catch(x=>log(x.message));['search','genreFilter','statusFilter'].forEach(id=>$(id).oninput=render);$('verifySelected').onclick=()=>markSelected(true);$('reviewSelected').onclick=()=>markSelected(false);$('deleteSelected').onclick=deleteSelected;$('exportMaster').onclick=()=>download('dj-folsoe-master-library.csv',exportMaster(tracks));$('exportSoundiiz').onclick=()=>download('dj-folsoe-soundiiz.csv',exportSoundiiz(tracks));$('exportTMM').onclick=()=>download('dj-folsoe-tunemymusic.csv',exportTuneMyMusic(tracks));$('exportWebsite').onclick=exportWebsite;$('generatePlan').onclick=generatePlan;$('closePlan').onclick=()=>$('planDialog').close();$('approvePlan').onclick=approvePlan;$('publishPlan').onclick=()=>publishPlan().catch(e=>log(e.message));$('planMaster').onclick=()=>{const list=currentPlan.trackIds.map(id=>tracks.find(t=>t.id===id)).filter(Boolean);download(`${currentPlan.showId}-${currentPlan.date}.csv`,exportMaster(list))};$('planSoundiiz').onclick=()=>{const list=currentPlan.trackIds.map(id=>tracks.find(t=>t.id===id)).filter(Boolean);download(`${currentPlan.showId}-${currentPlan.date}-soundiiz.csv`,exportSoundiiz(list))};$('planTMM').onclick=()=>{const list=currentPlan.trackIds.map(id=>tracks.find(t=>t.id===id)).filter(Boolean);download(`${currentPlan.showId}-${currentPlan.date}-tunemymusic.csv`,exportTuneMyMusic(list))};$('resetDb').onclick=resetDb;init().catch(e=>{log('STARTFEJL: '+e.message);console.error(e)});

